package com.universe.school.service;
import com.universe.global.exception.*; import com.universe.global.security.CurrentUser; import com.universe.school.dto.request.*; import com.universe.school.dto.response.*; import com.universe.school.entity.*; import com.universe.school.repository.*; import com.universe.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class SchoolVerificationService {private final SchoolRepository schools;private final SchoolVerificationRepository verifications;private final UserRepository users;private final SchoolVerificationCodeService codes;private final SchoolMailService mail;
 @Transactional public SchoolVerificationResponse request(SchoolVerificationRequest r){var u=users.findById(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHORIZED));if(Boolean.TRUE.equals(u.getSchoolVerified()))throw new BusinessException(ErrorCode.ALREADY_VERIFIED);var s=schools.findById(r.getSchoolId()).orElseThrow(()->new BusinessException(ErrorCode.SCHOOL_NOT_FOUND));if(s.getStatus()!=SchoolStatus.ACTIVE)throw new BusinessException(ErrorCode.SCHOOL_NOT_ACTIVE);String domain=r.getSchoolEmail().substring(r.getSchoolEmail().indexOf('@')+1).toLowerCase();if(s.getEmailDomain()!=null&&!s.getEmailDomain().equalsIgnoreCase(domain))throw new BusinessException(ErrorCode.SCHOOL_EMAIL_DOMAIN_MISMATCH);var v=verifications.save(SchoolVerification.builder().user(u).school(s).schoolEmail(r.getSchoolEmail()).build());String code=codes.issue(v.getId());mail.send(r.getSchoolEmail(),code);return SchoolVerificationResponse.from(v);}
 @Transactional public SchoolVerificationResponse confirm(Long id,SchoolVerificationConfirmRequest r){var u=users.findById(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHORIZED));var v=verifications.findById(id).orElseThrow(()->new BusinessException(ErrorCode.VERIFICATION_NOT_FOUND));if(!v.getUser().getId().equals(u.getId()))throw new BusinessException(ErrorCode.FORBIDDEN);if(v.getStatus()!=VerificationStatus.PENDING)throw new BusinessException(ErrorCode.VERIFICATION_EXPIRED);if(!codes.matches(id,r.getVerificationCode()))throw new BusinessException(ErrorCode.VERIFICATION_CODE_MISMATCH);v.verify();u.verifySchool(v.getSchool());codes.remove(id);return SchoolVerificationResponse.from(v);}
 @Transactional(readOnly=true) public SchoolVerificationResponse me(){var v=verifications.findTopByUserIdOrderByCreatedAtDesc(CurrentUser.id()).orElseThrow(()->new BusinessException(ErrorCode.VERIFICATION_NOT_FOUND));return SchoolVerificationResponse.from(v);}}
